#include "stdlib/lapack/base/dlaswp.h"
#include "stdlib/lapack/base/shared.h"
#include "stdlib/blas/base/dswap.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"
#include <stdint.h>

#define BLOCK_SIZE 32

/**
* Performs a series of row interchanges on a matrix `A` using pivot indices stored in `IPIV` and alternative indexing semantics.
*
* @param N           number of columns in `A`
* @param A           input matrix
* @param strideA1    stride of the first dimension of `A`
* @param strideA2    stride of the second dimension of `A`
* @param offsetA     starting index for `A`
* @param k1          index of first row to interchange
* @param k2          index of last row to interchange
* @param inck        direction in which to apply pivots (-1 to apply pivots in reverse order; otherwise, apply in provided order)
* @param IPIV        vector of pivot indices
* @param strideIPIV  `IPIV` stride length
* @param offsetIPIV  starting index for `IPIV`
*/
void API_SUFFIX(c_dlaswp_ndarray)( const LAPACK_INT N, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, const LAPACK_INT k1, const LAPACK_INT k2, const LAPACK_INT inck, const LAPACK_INT *IPIV, const LAPACK_INT strideIPIV, const LAPACK_INT offsetIPIV ) {
	int64_t sa[ 2 ];
	LAPACK_INT nrows;
	LAPACK_INT n32;
	LAPACK_INT row;
	LAPACK_INT ia1;
	LAPACK_INT ia2;
	LAPACK_INT ip;
	LAPACK_INT i;
	LAPACK_INT j;
	LAPACK_INT k;
	LAPACK_INT n;
	LAPACK_INT o;
	double tmp;

	// Compute the number of rows to be interchanged:
	if ( inck > 0 ) {
		nrows = k2 - k1;
	} else {
		nrows = k1 - k2;
	}
	nrows += 1;

	// Extract the strides for purposes of determining layout:
	sa[ 0 ] = strideA1;
	sa[ 1 ] = strideA2;

	// If the order is row-major, we can delegate to the Level 1 routine `dswap` for interchanging rows...
	if ( stdlib_ndarray_is_row_major( 2, sa ) ) {
		ip = offsetIPIV;
		for ( i = 0, k = k1; i < nrows; i++, k += inck ) {
			row = IPIV[ ip ];
			if ( row != k ) {
				c_dswap_ndarray( N, A, strideA2, offsetA + ( k * strideA1 ), A, strideA2, offsetA + ( row * strideA1 ) );
			}
			ip += strideIPIV;
		}
		return;
	}
	// If the order is column-major, we need to use loop tiling to ensure efficient cache access when accessing matrix elements...
	n32 = ( N / BLOCK_SIZE ) * BLOCK_SIZE;
	if ( n32 != 0 ) {
		for ( j = 0; j < n32; j += BLOCK_SIZE ) {
			ip = offsetIPIV;
			for ( i = 0, k = k1; i < nrows; i++, k += inck ) {
				row = IPIV[ ip ];
				if ( row != k ) {
					ia1 = offsetA + ( k * strideA1 );
					ia2 = offsetA + ( row * strideA1 );
					for ( n = j; n < j + BLOCK_SIZE; n++ ) {
						o = n * strideA2;
						tmp = A[ ia1+o ];
						A[ ia1+o ] = A[ ia2+o ];
						A[ ia2+o ] = tmp;
					}
				}
				ip += strideIPIV;
			}
		}
	}
	if ( n32 != N ) {
		ip = offsetIPIV;
		for ( i = 0, k = k1; i < nrows; i++, k += inck ) {
			row = IPIV[ ip ];
			if ( row != k ) {
				ia1 = offsetA + ( k * strideA1 );
				ia2 = offsetA + ( row * strideA1 );
				for ( n = n32; n < N; n++ ) {
					o = n * strideA2;
					tmp = A[ ia1+o ];
					A[ ia1+o ] = A[ ia2+o ];
					A[ ia2+o ] = tmp;
				}
			}
			ip += strideIPIV;
		}
	}
}
